(1496817,52,12,5,25,'וְ/הוּא־בָא֙וַ/יַּעֲמֹ֣דאֶל־אֲדֹנָ֔י/ווַ/יֹּ֤אמֶראֵלָי/ו֙אֱלִישָׁ֔עגֵּחֲזִ֑יוַ/יֹּ֕אמֶרלֹֽא־הָלַ֥ךְעַבְדְּ/ךָ֖אָ֥נֶהוָ/אָֽנָה׃'),
(1496818,52,12,5,26,'וַ/יֹּ֤אמֶראֵלָי/ו֙לֹא־לִבִּ֣/יהָלַ֔ךְכַּ/אֲשֶׁ֧רהָֽפַךְ־אִ֛ישׁמֵ/עַ֥למֶרְכַּבְתּ֖/וֹלִ/קְרָאתֶ֑/ךָהַ/עֵ֞תלָ/קַ֤חַתאֶת־הַ/כֶּ֙סֶף֙וְ/לָ/קַ֣חַתבְּגָדִ֔יםוְ/זֵיתִ֤יםוּ/כְרָמִים֙וְ/צֹ֣אןוּ/בָקָ֔רוַ/עֲבָדִ֖יםוּ/שְׁפָחֽוֹת׃'),
(1496819,52,12,5,27,'וְ/צָרַ֤עַתנַֽעֲמָן֙תִּֽדְבַּק־בְּ/ךָ֔וּֽ/בְ/זַרְעֲ/ךָלְ/עוֹלָ֑םוַ/יֵּצֵ֥אמִ/לְּ/פָנָ֖י/ומְצֹרָ֥עכַּ/שָּֽׁלֶג׃'),
(1496820,52,12,6,1,'וַ/יֹּאמְר֥וּבְנֵֽי־הַ/נְּבִיאִ֖יםאֶל־אֱלִישָׁ֑עהִנֵּֽה־נָ֣אהַ/מָּק֗וֹםאֲשֶׁ֨ראֲנַ֜חְנוּיֹשְׁבִ֥יםשָׁ֛םלְ/פָנֶ֖י/ךָצַ֥רמִמֶּֽ/נּוּ׃'),
(1496821,52,12,6,2,'נֵֽלְכָה־נָּ֣אעַד־הַ/יַּרְדֵּ֗ןוְ/נִקְחָ֤המִ/שָּׁם֙אִ֚ישׁקוֹרָ֣האֶחָ֔תוְ/נַעֲשֶׂה־לָּ֥/נוּשָׁ֛םמָק֖וֹםלָ/שֶׁ֣בֶתשָׁ֑םוַ/יֹּ֖אמֶרלֵֽכוּ׃'),
(1496822,52,12,6,3,'וַ/יֹּ֙אמֶר֙הָֽ/אֶחָ֔דה֥וֹאֶלנָ֖אוְ/לֵ֣ךְאֶת־עֲבָדֶ֑י/ךָוַ/יֹּ֖אמֶראֲנִ֥יאֵלֵֽךְ׃'),
(1496823,52,12,6,4,'וַ/יֵּ֖לֶךְאִתָּ֑/םוַ/יָּבֹ֙אוּ֙הַ/יַּרְדֵּ֔נָ/הוַֽ/יִּגְזְר֖וּהָ/עֵצִֽים׃'),
(1496824,52,12,6,5,'וַ/יְהִ֤יהָֽ/אֶחָד֙מַפִּ֣ילהַ/קּוֹרָ֔הוְ/אֶת־הַ/בַּרְזֶ֖לנָפַ֣לאֶל־הַ/מָּ֑יִםוַ/יִּצְעַ֥קוַ/יֹּ֛אמֶראֲהָ֥הּאֲדֹנִ֖/יוְ/ה֥וּאשָׁאֽוּל׃'),
(1496825,52,12,6,6,'וַ/יֹּ֥אמֶראִישׁ־הָ/אֱלֹהִ֖יםאָ֣נָהנָפָ֑לוַ/יַּרְאֵ֙/הוּ֙אֶת־הַ/מָּק֔וֹםוַ/יִּקְצָב־עֵץ֙וַ/יַּשְׁלֶךְ־שָׁ֔מָּ/הוַ/יָּ֖צֶףהַ/בַּרְזֶֽל׃'),
(1496826,52,12,6,7,'וַ/יֹּ֖אמֶרהָ֣רֶםלָ֑/ךְוַ/יִּשְׁלַ֥חיָד֖/וֹוַ/יִּקָּחֵֽ/הוּ׃'),
(1496827,52,12,6,8,'וּ/מֶ֣לֶךְאֲרָ֔םהָיָ֥הנִלְחָ֖םבְּ/יִשְׂרָאֵ֑לוַ/יִּוָּעַץ֙אֶל־עֲבָדָ֣י/ולֵ/אמֹ֗ראֶל־מְק֛וֹםפְּלֹנִ֥יאַלְמֹנִ֖יתַּחֲנֹתִֽ/י׃'),
(1496828,52,12,6,9,'וַ/יִּשְׁלַ֞חאִ֣ישׁהָ/אֱלֹהִ֗יםאֶל־מֶ֤לֶךְיִשְׂרָאֵל֙לֵ/אמֹ֔רהִשָּׁ֕מֶרמֵ/עֲבֹ֖רהַ/מָּק֣וֹםהַ/זֶּ֑הכִּֽי־שָׁ֖םאֲרָ֥םנְחִתִּֽים׃'),
(1496829,52,12,6,10,'וַ/יִּשְׁלַ֞חמֶ֣לֶךְיִשְׂרָאֵ֗לאֶֽל־הַ/מָּק֞וֹםאֲשֶׁ֨ראָֽמַר־ל֧/וֹאִישׁ־הָ/אֱלֹהִ֛יםוְ/נִשְׁמַ֣רשָׁ֑םלֹ֥אאַחַ֖תוְ/לֹ֥אשְׁתָּֽיִם׃'),
(1496830,52,12,6,11,'וַ/יִּסָּעֵר֙לֵ֣במֶֽלֶךְ־אֲרָ֔םעַל־הַ/דָּבָ֖רהַ/זֶּ֑הוַ/יִּקְרָ֤אאֶל־עֲבָדָי/ו֙וַ/יֹּ֣אמֶראֲלֵי/הֶ֔םהֲ/לוֹא֙תַּגִּ֣ידוּלִ֔/ימִ֥ימִ/שֶּׁ/לָּ֖/נוּאֶל־מֶ֥לֶךְיִשְׂרָאֵֽל׃'),
(1496831,52,12,6,12,'וַ/יֹּ֙אמֶר֙אַחַ֣דמֵֽ/עֲבָדָ֔י/ול֖וֹאאֲדֹנִ֣/יהַ/מֶּ֑לֶךְכִּֽי־אֱלִישָׁ֤עהַ/נָּבִיא֙אֲשֶׁ֣רבְּ/יִשְׂרָאֵ֔ליַגִּיד֙לְ/מֶ֣לֶךְיִשְׂרָאֵ֔לאֶת־הַ֨/דְּבָרִ֔יםאֲשֶׁ֥רתְּדַבֵּ֖רבַּ/חֲדַ֥רמִשְׁכָּבֶֽ/ךָ׃'),
(1496832,52,12,6,13,'וַ/יֹּ֗אמֶרלְכ֤וּוּ/רְאוּ֙אֵיכֹ֣הה֔וּאוְ/אֶשְׁלַ֖חוְ/אֶקָּחֵ֑/הוּוַ/יֻּגַּד־ל֥/וֹלֵ/אמֹ֖רהִנֵּ֥הבְ/דֹתָֽן׃'),
(1496833,52,12,6,14,'וַ/יִּשְׁלַח־שָׁ֛מָּ/הסוּסִ֥יםוְ/רֶ֖כֶבוְ/חַ֣יִלכָּבֵ֑דוַ/יָּבֹ֣אוּלַ֔יְלָהוַ/יַּקִּ֖פוּעַל־הָ/עִֽיר׃'),
(1496834,52,12,6,15,'וַ֠/יַּשְׁכֵּםמְשָׁרֵ֨תאִ֥ישׁהָֽ/אֱלֹהִים֮לָ/קוּם֒וַ/יֵּצֵ֕אוְ/הִנֵּה־חַ֛יִלסוֹבֵ֥באֶת־הָ/עִ֖ירוְ/ס֣וּסוָ/רָ֑כֶבוַ/יֹּ֨אמֶרנַעֲר֥/וֹאֵלָ֛י/ואֲהָ֥הּאֲדֹנִ֖/יאֵיכָ֥הנַֽעֲשֶֽׂה׃'),
(1496835,52,12,6,16,'וַ/יֹּ֖אמֶראַל־תִּירָ֑אכִּ֤ירַבִּים֙אֲשֶׁ֣ראִתָּ֔/נוּמֵ/אֲשֶׁ֖ראוֹתָֽ/ם׃'),
(1496836,52,12,6,17,'וַ/יִּתְפַּלֵּ֤לאֱלִישָׁע֙וַ/יֹּאמַ֔ריְהוָ֕הפְּקַח־נָ֥אאֶת־עֵינָ֖י/ווְ/יִרְאֶ֑הוַ/יִּפְקַ֤חיְהוָה֙אֶת־עֵינֵ֣יהַ/נַּ֔עַרוַ/יַּ֗רְאוְ/הִנֵּ֨ההָ/הָ֜רמָלֵ֨אסוּסִ֥יםוְ/רֶ֛כֶבאֵ֖שׁסְבִיבֹ֥תאֱלִישָֽׁע׃'),
(1496837,52,12,6,18,'וַ/יֵּרְדוּ֮אֵלָי/ו֒וַ/יִּתְפַּלֵּ֨לאֱלִישָׁ֤עאֶל־יְהוָה֙וַ/יֹּאמַ֔רהַךְ־נָ֥אאֶת־הַ/גּוֹי־הַ/זֶּ֖הבַּ/סַּנְוֵרִ֑יםוַ/יַּכֵּ֥/םבַּ/סַּנְוֵרִ֖יםכִּ/דְבַ֥ראֱלִישָֽׁע׃'),
(1496838,52,12,6,19,'וַ/יֹּ֨אמֶראֲלֵ/הֶ֜םאֱלִישָׁ֗עלֹ֣אזֶ֣ההַ/דֶּרֶךְ֮וְ/לֹ֣אזֹ֣ההָ/עִיר֒לְכ֣וּאַחֲרַ֔/יוְ/אוֹלִ֣יכָהאֶתְ/כֶ֔םאֶל־הָ/אִ֖ישׁאֲשֶׁ֣רתְּבַקֵּשׁ֑וּ/ןוַ/יֹּ֥לֶךְאוֹתָ֖/םשֹׁמְרֽוֹנָ/ה׃'),
(1496839,52,12,6,20,'וַ/יְהִי֮כְּ/בֹאָ֣/םשֹׁמְרוֹן֒וַ/יֹּ֣אמֶראֱלִישָׁ֔עיְהוָ֕הפְּקַ֥חאֶת־עֵינֵֽי־אֵ֖לֶּהוְ/יִרְא֑וּוַ/יִּפְקַ֤חיְהוָה֙אֶת־עֵ֣ינֵי/הֶ֔םוַ/יִּרְא֕וּוְ/הִנֵּ֖הבְּ/ת֥וֹךְשֹׁמְרֽוֹן׃'),
(1496840,52,12,6,21,'וַ/יֹּ֤אמֶרמֶֽלֶךְ־יִשְׂרָאֵל֙אֶל־אֱלִישָׁ֔עכִּ/רְאֹת֖/וֹאוֹתָ֑/םהַ/אַכֶּ֥האַכֶּ֖האָבִֽ/י׃'),
(1496841,52,12,6,22,'וַ/יֹּ֙אמֶר֙לֹ֣אתַכֶּ֔ההַ/אֲשֶׁ֥רשָׁבִ֛יתָבְּ/חַרְבְּ/ךָ֥וּֽ/בְ/קַשְׁתְּ/ךָ֖אַתָּ֣המַכֶּ֑השִׂים֩לֶ֨חֶםוָ/מַ֜יִםלִ/פְנֵי/הֶ֗םוְ/יֹֽאכְלוּ֙וְ/יִשְׁתּ֔וּוְ/יֵלְכ֖וּאֶל־אֲדֹנֵי/הֶֽם׃'),
(1496842,52,12,6,23,'וַ/יִּכְרֶ֨הלָ/הֶ֜םכֵּרָ֣הגְדוֹלָ֗הוַ/יֹּֽאכְלוּ֙וַ/יִּשְׁתּ֔וּוַֽ/יְשַׁלְּחֵ֔/םוַ/יֵּלְכ֖וּאֶל־אֲדֹֽנֵי/הֶ֑םוְ/לֹֽא־יָ֤סְפוּעוֹד֙גְּדוּדֵ֣יאֲרָ֔םלָ/ב֖וֹאבְּ/אֶ֥רֶץיִשְׂרָאֵֽל׃'),
(1496843,52,12,6,24,'וַֽ/יְהִי֙אַחֲרֵי־כֵ֔ןוַ/יִּקְבֹּ֛ץבֶּן־הֲדַ֥דמֶֽלֶךְ־אֲרָ֖םאֶת־כָּל־מַחֲנֵ֑/הוּוַ/יַּ֕עַלוַ/יָּ֖צַרעַל־שֹׁמְרֽוֹן׃'),
(1496844,52,12,6,25,'וַ/יְהִ֨ירָעָ֤בגָּדוֹל֙בְּ/שֹׁ֣מְר֔וֹןוְ/הִנֵּ֖הצָרִ֣יםעָלֶ֑י/הָעַ֣דהֱי֤וֹתרֹאשׁ־חֲמוֹר֙בִּ/שְׁמֹנִ֣יםכֶּ֔סֶףוְ/רֹ֛בַעהַ/קַּ֥בבַּ/חֲמִשָּׁה־כָֽסֶף׃'),
(1496845,52,12,6,26,'וַֽ/יְהִי֙מֶ֣לֶךְיִשְׂרָאֵ֔לעֹבֵ֖רעַל־הַ/חֹמָ֑הוְ/אִשָּׁ֗הצָעֲקָ֤האֵלָי/ו֙לֵ/אמֹ֔רהוֹשִׁ֖יעָ/האֲדֹנִ֥/יהַ/מֶּֽלֶךְ׃'),
(1496846,52,12,6,27,'וַ/יֹּ֙אמֶר֙אַל־יוֹשִׁעֵ֣/ךְיְהוָ֔המֵ/אַ֖יִןאֽוֹשִׁיעֵ֑/ךְהֲ/מִן־הַ/גֹּ֖רֶןא֥וֹמִן־הַ/יָּֽקֶב׃');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1496847,52,12,6,28,'וַ/יֹּֽאמֶר־לָ֥/הּהַ/מֶּ֖לֶךְמַה־לָּ֑/ךְוַ/תֹּ֗אמֶרהָ/אִשָּׁ֨ההַ/זֹּ֜אתאָמְרָ֣האֵלַ֗/יתְּנִ֤יאֶת־בְּנֵ/ךְ֙וְ/נֹאכְלֶ֣/נּוּהַ/יּ֔וֹםוְ/אֶת־בְּנִ֖/ינֹאכַ֥למָחָֽר׃'),
(1496848,52,12,6,29,'וַ/נְּבַשֵּׁ֥לאֶת־בְּנִ֖/יוַ/נֹּֽאכְלֵ֑/הוּוָ/אֹמַ֨ראֵלֶ֜י/הָבַּ/יּ֣וֹםהָ/אַחֵ֗רתְּנִ֤יאֶת־בְּנֵ/ךְ֙וְ/נֹ֣אכְלֶ֔/נּוּוַ/תַּחְבִּ֖אאֶת־בְּנָֽ/הּ׃'),
(1496849,52,12,6,30,'וַ/יְהִי֩כִ/שְׁמֹ֨עַהַ/מֶּ֜לֶךְאֶת־דִּבְרֵ֤יהָֽ/אִשָּׁה֙וַ/יִּקְרַ֣עאֶת־בְּגָדָ֔י/ווְ/ה֖וּאעֹבֵ֣רעַל־הַ/חֹמָ֑הוַ/יַּ֣רְאהָ/עָ֔םוְ/הִנֵּ֥ההַ/שַּׂ֛קעַל־בְּשָׂר֖/וֹמִ/בָּֽיִת׃'),
(1496850,52,12,6,31,'וַ/יֹּ֕אמֶרכֹּֽה־יַעֲשֶׂה־לִּ֥/יאֱלֹהִ֖יםוְ/כֹ֣היוֹסִ֑ףאִֽם־יַעֲמֹ֞דרֹ֣אשׁאֱלִישָׁ֧עבֶּן־שָׁפָ֛טעָלָ֖י/והַ/יּֽוֹם׃'),
(1496851,52,12,6,32,'וֶ/אֱלִישָׁע֙יֹשֵׁ֣בבְּ/בֵית֔/וֹוְ/הַ/זְּקֵנִ֖יםיֹשְׁבִ֣יםאִתּ֑/וֹוַ/יִּשְׁלַ֨חאִ֜ישׁמִ/לְּ/פָנָ֗י/ובְּ/טֶ֣רֶםיָבֹא֩הַ/מַּלְאָ֨ךְאֵלָ֜י/ווְ/ה֣וּא ׀אָמַ֣ראֶל־הַ/זְּקֵנִ֗יםהַ/רְּאִיתֶם֙כִּֽי־שָׁלַ֞חבֶּן־הַֽ/מְרַצֵּ֤חַהַ/זֶּה֙לְ/הָסִ֣יראֶת־רֹאשִׁ֔/ירְא֣וּ ׀כְּ/בֹ֣אהַ/מַּלְאָ֗ךְסִגְר֤וּהַ/דֶּ֙לֶת֙וּ/לְחַצְתֶּ֤םאֹת/וֹ֙בַּ/דֶּ֔לֶתהֲ/ל֗וֹאק֛וֹלרַגְלֵ֥יאֲדֹנָ֖י/ואַחֲרָֽי/ו׃'),
