(1497001,52,12,12,7,'וַ/יְהִ֗יבִּ/שְׁנַ֨תעֶשְׂרִ֧יםוְ/שָׁלֹ֛שׁשָׁנָ֖הלַ/מֶּ֣לֶךְיְהוֹאָ֑שׁלֹֽא־חִזְּק֥וּהַ/כֹּהֲנִ֖יםאֶת־בֶּ֥דֶקהַ/בָּֽיִת׃'),
(1497002,52,12,12,8,'וַ/יִּקְרָא֩הַ/מֶּ֨לֶךְיְהוֹאָ֜שׁלִ/יהוֹיָדָ֤עהַ/כֹּהֵן֙וְ/לַ/כֹּ֣הֲנִ֔יםוַ/יֹּ֣אמֶראֲלֵ/הֶ֔םמַדּ֛וּעַאֵינְ/כֶ֥םמְחַזְּקִ֖יםאֶת־בֶּ֣דֶקהַ/בָּ֑יִתוְ/עַתָּ֗האַל־תִּקְחוּ־כֶ֙סֶף֙מֵ/אֵ֣תמַכָּֽרֵי/כֶ֔םכִּֽי־לְ/בֶ֥דֶקהַ/בַּ֖יִתתִּתְּנֻֽ/הוּ׃'),
(1497003,52,12,12,9,'וַ/יֵּאֹ֖תוּהַ/כֹּֽהֲנִ֑יםלְ/בִלְתִּ֤יקְחַת־כֶּ֙סֶף֙מֵ/אֵ֣תהָ/עָ֔םוּ/לְ/בִלְתִּ֥יחַזֵּ֖קאֶת־בֶּ֥דֶקהַ/בָּֽיִת׃'),
(1497004,52,12,12,10,'וַ/יִּקַּ֞חיְהוֹיָדָ֤עהַ/כֹּהֵן֙אֲר֣וֹןאֶחָ֔דוַ/יִּקֹּ֥בחֹ֖רבְּ/דַלְתּ֑/וֹוַ/יִּתֵּ֣ןאֹת/וֹ֩אֵ֨צֶלהַ/מִּזְבֵּ֜חַבְּ/בֽוֹא־אִישׁ֙בֵּ֣יתיְהוָ֔הוְ/נָֽתְנוּ־שָׁ֤מָּ/ההַ/כֹּֽהֲנִים֙שֹׁמְרֵ֣יהַ/סַּ֔ףאֶת־כָּל־הַ/כֶּ֖סֶףהַ/מּוּבָ֥אבֵית־יְהוָֽה׃'),
(1497005,52,12,12,11,'וַֽ/יְהִי֙כִּ/רְאוֹתָ֔/םכִּֽי־רַ֥בהַ/כֶּ֖סֶףבָּֽ/אָר֑וֹןוַ/יַּ֨עַלסֹפֵ֤רהַ/מֶּ֙לֶךְ֙וְ/הַ/כֹּהֵ֣ןהַ/גָּד֔וֹלוַ/יָּצֻ֙רוּ֙וַ/יִּמְנ֔וּאֶת־הַ/כֶּ֖סֶףהַ/נִּמְצָ֥אבֵית־יְהוָֽה׃'),
(1497006,52,12,12,12,'וְ/נָתְנוּ֙אֶת־הַ/כֶּ֣סֶףהַֽ/מְתֻכָּ֔ןעַל־עֹשֵׂ֣יהַ/מְּלָאכָ֔הבֵּ֣יתיְהוָ֑הוַ/יּוֹצִיאֻ֜/הוּלְ/חָרָשֵׁ֤יהָ/עֵץ֙וְ/לַ/בֹּנִ֔יםהָ/עֹשִׂ֖יםבֵּ֥יתיְהוָֽה׃'),
(1497007,52,12,12,13,'וְ/לַ/גֹּֽדְרִים֙וּ/לְ/חֹצְבֵ֣יהָ/אֶ֔בֶןוְ/לִ/קְנ֤וֹתעֵצִים֙וְ/אַבְנֵ֣ימַחְצֵ֔בלְ/חַזֵּ֖קאֶת־בֶּ֣דֶקבֵּית־יְהוָ֑הוּ/לְ/כֹ֛לאֲשֶׁר־יֵצֵ֥אעַל־הַ/בַּ֖יִתלְ/חָזְקָֽה׃'),
(1497008,52,12,12,14,'אַךְ֩לֹ֨איֵעָשֶׂ֜הבֵּ֣יתיְהוָ֗הסִפּ֥וֹתכֶּ֙סֶף֙מְזַמְּר֤וֹתמִזְרָקוֹת֙חֲצֹ֣צְר֔וֹתכָּל־כְּלִ֥יזָהָ֖בוּ/כְלִי־כָ֑סֶףמִן־הַ/כֶּ֖סֶףהַ/מּוּבָ֥אבֵית־יְהוָֽה׃'),
(1497009,52,12,12,15,'כִּֽי־לְ/עֹשֵׂ֥יהַ/מְּלָאכָ֖היִתְּנֻ֑/הוּוְ/חִזְּקוּ־ב֖/וֹאֶת־בֵּ֥יתיְהוָֽה׃'),
(1497010,52,12,12,16,'וְ/לֹ֧איְחַשְּׁב֣וּאֶת־הָ/אֲנָשִׁ֗יםאֲשֶׁ֨ריִתְּנ֤וּאֶת־הַ/כֶּ֙סֶף֙עַל־יָדָ֔/םלָ/תֵ֖תלְ/עֹשֵׂ֣יהַ/מְּלָאכָ֑הכִּ֥יבֶ/אֱמֻנָ֖ההֵ֥םעֹשִֽׂים׃'),
(1497011,52,12,12,17,'כֶּ֤סֶףאָשָׁם֙וְ/כֶ֣סֶףחַטָּא֔וֹתלֹ֥איוּבָ֖אבֵּ֣יתיְהוָ֑הלַ/כֹּהֲנִ֖יםיִהְיֽוּ׃'),
(1497012,52,12,12,18,'אָ֣זיַעֲלֶ֗החֲזָאֵל֙מֶ֣לֶךְאֲרָ֔םוַ/יִּלָּ֥חֶםעַל־גַּ֖תוַֽ/יִּלְכְּדָ֑/הּוַ/יָּ֤שֶׂםחֲזָאֵל֙פָּנָ֔י/ולַ/עֲל֖וֹתעַל־יְרוּשָׁלִָֽם׃'),
(1497013,52,12,12,19,'וַ/יִּקַּ֞חיְהוֹאָ֣שׁמֶֽלֶךְ־יְהוּדָ֗האֵ֣תכָּל־הַ/קֳּדָשִׁ֡יםאֲשֶׁר־הִקְדִּ֣ישׁוּיְהוֹשָׁפָ֣טוִ/יהוֹרָם֩וַ/אֲחַזְיָ֨הוּאֲבֹתָ֜י/ומַלְכֵ֤ייְהוּדָה֙וְ/אֶת־קֳדָשָׁ֔י/ווְ/אֵ֣תכָּל־הַ/זָּהָ֗בהַ/נִּמְצָ֛אבְּ/אֹצְר֥וֹתבֵּית־יְהוָ֖הוּ/בֵ֣יתהַ/מֶּ֑לֶךְוַ/יִּשְׁלַ֗חלַֽ/חֲזָאֵל֙מֶ֣לֶךְאֲרָ֔םוַ/יַּ֖עַלמֵ/עַ֥ליְרוּשָׁלִָֽם׃'),
(1497014,52,12,12,20,'וְ/יֶ֛תֶרדִּבְרֵ֥ייוֹאָ֖שׁוְ/כָל־אֲשֶׁ֣רעָשָׂ֑ההֲ/לוֹא־הֵ֣םכְּתוּבִ֗יםעַל־סֵ֛פֶרדִּבְרֵ֥יהַ/יָּמִ֖יםלְ/מַלְכֵ֥ייְהוּדָֽה׃'),
(1497015,52,12,12,21,'וַ/יָּקֻ֥מוּעֲבָדָ֖י/ווַ/יִּקְשְׁרֽוּ־קָ֑שֶׁרוַ/יַּכּוּ֙אֶת־יוֹאָ֔שׁבֵּ֥יתמִלֹּ֖אהַ/יּוֹרֵ֥דסִלָּֽא׃'),
(1497016,52,12,12,22,'וְ/יוֹזָבָ֣דבֶּן־שִׁ֠מְעָתוִ/יהוֹזָבָ֨דבֶּן־שֹׁמֵ֤ר ׀עֲבָדָי/ו֙הִכֻּ֣/הוּוַ/יָּמֹ֔תוַ/יִּקְבְּר֥וּאֹת֛/וֹעִם־אֲבֹתָ֖י/ובְּ/עִ֣ירדָּוִ֑דוַ/יִּמְלֹ֛ךְאֲמַצְיָ֥הבְנ֖/וֹתַּחְתָּֽי/ו׃'),
(1497017,52,12,13,1,'בִּ/שְׁנַ֨תעֶשְׂרִ֤יםוְ/שָׁלֹשׁ֙שָׁנָ֔הלְ/יוֹאָ֥שׁבֶּן־אֲחַזְיָ֖הוּמֶ֣לֶךְיְהוּדָ֑המָ֠לַךְיְהוֹאָחָ֨זבֶּן־יֵה֤וּאעַל־יִשְׂרָאֵל֙בְּ/שֹׁ֣מְר֔וֹןשְׁבַ֥עעֶשְׂרֵ֖השָׁנָֽה׃'),
(1497018,52,12,13,2,'וַ/יַּ֥עַשׂהָ/רַ֖עבְּ/עֵינֵ֣ייְהוָ֑הוַ֠/יֵּלֶךְאַחַ֨רחַטֹּ֜אתיָרָבְעָ֧םבֶּן־נְבָ֛טאֲשֶׁר־הֶחֱטִ֥יאאֶת־יִשְׂרָאֵ֖ללֹא־סָ֥רמִמֶּֽ/נָּה׃'),
(1497019,52,12,13,3,'וַ/יִּֽחַר־אַ֥ףיְהוָ֖הבְּ/יִשְׂרָאֵ֑לוַֽ/יִּתְּנֵ֞/םבְּ/יַ֣ד ׀חֲזָאֵ֣למֶֽלֶךְ־אֲרָ֗םוּ/בְ/יַ֛דבֶּן־הֲדַ֥דבֶּן־חֲזָאֵ֖לכָּל־הַ/יָּמִֽים׃'),
(1497020,52,12,13,4,'וַ/יְחַ֥ליְהוֹאָחָ֖זאֶת־פְּנֵ֣ייְהוָ֑הוַ/יִּשְׁמַ֤עאֵלָי/ו֙יְהוָ֔הכִּ֤ירָאָה֙אֶת־לַ֣חַץיִשְׂרָאֵ֔לכִּֽי־לָחַ֥ץאֹתָ֖/םמֶ֥לֶךְאֲרָֽם׃'),
(1497021,52,12,13,5,'וַ/יִּתֵּ֨ןיְהוָ֤הלְ/יִשְׂרָאֵל֙מוֹשִׁ֔יעַוַ/יֵּ֣צְא֔וּמִ/תַּ֖חַתיַד־אֲרָ֑םוַ/יֵּשְׁב֧וּבְנֵֽי־יִשְׂרָאֵ֛לבְּ/אָהֳלֵי/הֶ֖םכִּ/תְמ֥וֹלשִׁלְשֽׁוֹם׃'),
(1497022,52,12,13,6,'אַ֠ךְלֹֽא־סָ֜רוּמֵ/חַטֹּ֧אותבֵּית־יָרָבְעָ֛םאֲשֶׁר־אֶת־יִשְׂרָאֵ֖לבָּ֣/הּהָלָ֑ךְוְ/גַם֙הָ/אֲשֵׁרָ֔העָמְדָ֖הבְּ/שֹׁמְרֽוֹן׃'),
(1497023,52,12,13,7,'כִּ֣ילֹא֩הִשְׁאִ֨ירלִ/יהוֹאָחָ֜זעָ֗םכִּ֣יאִם־חֲמִשִּׁ֤יםפָּֽרָשִׁים֙וַ/עֲשָׂ֣רָהרֶ֔כֶבוַ/עֲשֶׂ֥רֶתאֲלָפִ֖יםרַגְלִ֑יכִּ֤יאִבְּדָ/ם֙מֶ֣לֶךְאֲרָ֔םוַ/יְשִׂמֵ֥/םכֶּֽ/עָפָ֖רלָ/דֻֽשׁ׃'),
(1497024,52,12,13,8,'וְ/יֶ֨תֶרדִּבְרֵ֧ייְהוֹאָחָ֛זוְ/כָל־אֲשֶׁ֥רעָשָׂ֖הוּ/גְבוּרָת֑/וֹהֲ/לוֹא־הֵ֣םכְּתוּבִ֗יםעַל־סֵ֛פֶרדִּבְרֵ֥יהַ/יָּמִ֖יםלְ/מַלְכֵ֥ייִשְׂרָאֵֽל׃'),
(1497025,52,12,13,9,'וַ/יִּשְׁכַּ֤ביְהֽוֹאָחָז֙עִם־אֲבֹתָ֔י/ווַֽ/יִּקְבְּרֻ֖/הוּבְּ/שֹׁמְר֑וֹןוַ/יִּמְלֹ֛ךְיוֹאָ֥שׁבְּנ֖/וֹתַּחְתָּֽי/ו׃'),
(1497026,52,12,13,10,'בִּ/שְׁנַ֨תשְׁלֹשִׁ֤יםוָ/שֶׁ֙בַע֙שָׁנָ֔הלְ/יוֹאָ֖שׁמֶ֣לֶךְיְהוּדָ֑המָ֠לַךְיְהוֹאָ֨שׁבֶּן־יְהוֹאָחָ֤זעַל־יִשְׂרָאֵל֙בְּ/שֹׁ֣מְר֔וֹןשֵׁ֥שׁעֶשְׂרֵ֖השָׁנָֽה׃'),
