(1505812,52,2,38,23,'וְ/אִתּ֗/וֹאָהֳלִיאָ֞בבֶּן־אֲחִיסָמָ֛ךְלְ/מַטֵּה־דָ֖ןחָרָ֣שׁוְ/חֹשֵׁ֑בוְ/רֹקֵ֗םבַּ/תְּכֵ֙לֶת֙וּ/בָֽ/אַרְגָּמָ֔ןוּ/בְ/תוֹלַ֥עַתהַ/שָּׁנִ֖יוּ/בַ/שֵּֽׁשׁ׃'),
(1505813,52,2,38,24,'כָּל־הַ/זָּהָ֗בהֶֽ/עָשׂוּי֙לַ/מְּלָאכָ֔הבְּ/כֹ֖למְלֶ֣אכֶתהַ/קֹּ֑דֶשׁוַ/יְהִ֣י ׀זְהַ֣בהַ/תְּנוּפָ֗התֵּ֤שַׁעוְ/עֶשְׂרִים֙כִּכָּ֔רוּ/שְׁבַ֨עמֵא֧וֹתוּ/שְׁלֹשִׁ֛יםשֶׁ֖קֶלבְּ/שֶׁ֥קֶלהַ/קֹּֽדֶשׁ׃'),
(1505814,52,2,38,25,'וְ/כֶ֛סֶףפְּקוּדֵ֥יהָ/עֵדָ֖המְאַ֣תכִּכָּ֑רוְ/אֶלֶף֩וּ/שְׁבַ֨עמֵא֜וֹתוַ/חֲמִשָּׁ֧הוְ/שִׁבְעִ֛יםשֶׁ֖קֶלבְּ/שֶׁ֥קֶלהַ/קֹּֽדֶשׁ׃'),
(1505815,52,2,38,26,'בֶּ֚קַעלַ/גֻּלְגֹּ֔לֶתמַחֲצִ֥יתהַ/שֶּׁ֖קֶלבְּ/שֶׁ֣קֶלהַ/קֹּ֑דֶשׁלְ/כֹ֨להָ/עֹבֵ֜רעַל־הַ/פְּקֻדִ֗יםמִ/בֶּ֨ןעֶשְׂרִ֤יםשָׁנָה֙וָ/מַ֔עְלָ/הלְ/שֵׁשׁ־מֵא֥וֹתאֶ֙לֶף֙וּ/שְׁלֹ֣שֶׁתאֲלָפִ֔יםוַ/חֲמֵ֥שׁמֵא֖וֹתוַ/חֲמִשִּֽׁים׃'),
(1505816,52,2,38,27,'וַ/יְהִ֗ימְאַת֙כִּכַּ֣רהַ/כֶּ֔סֶףלָ/צֶ֗קֶתאֵ֚תאַדְנֵ֣יהַ/קֹּ֔דֶשׁוְ/אֵ֖תאַדְנֵ֣יהַ/פָּרֹ֑כֶתמְאַ֧תאֲדָנִ֛יםלִ/מְאַ֥תהַ/כִּכָּ֖רכִּכָּ֥רלָ/אָֽדֶן׃'),
(1505817,52,2,38,28,'וְ/אֶת־הָ/אֶ֜לֶףוּ/שְׁבַ֤עהַ/מֵּאוֹת֙וַ/חֲמִשָּׁ֣הוְ/שִׁבְעִ֔יםעָשָׂ֥הוָוִ֖יםלָ/עַמּוּדִ֑יםוְ/צִפָּ֥הרָאשֵׁי/הֶ֖םוְ/חִשַּׁ֥קאֹתָֽ/ם׃'),
(1505818,52,2,38,29,'וּ/נְחֹ֥שֶׁתהַ/תְּנוּפָ֖השִׁבְעִ֣יםכִּכָּ֑רוְ/אַלְפַּ֥יִםוְ/אַרְבַּע־מֵא֖וֹתשָֽׁקֶל׃'),
(1505819,52,2,38,30,'וַ/יַּ֣עַשׂבָּ֗/הּאֶת־אַדְנֵי֙פֶּ֚תַחאֹ֣הֶלמוֹעֵ֔דוְ/אֵת֙מִזְבַּ֣חהַ/נְּחֹ֔שֶׁתוְ/אֶת־מִכְבַּ֥רהַ/נְּחֹ֖שֶׁתאֲשֶׁר־ל֑/וֹוְ/אֵ֖תכָּל־כְּלֵ֥יהַ/מִּזְבֵּֽחַ׃'),
(1505820,52,2,38,31,'וְ/אֶת־אַדְנֵ֤יהֶֽ/חָצֵר֙סָבִ֔יבוְ/אֶת־אַדְנֵ֖ישַׁ֣עַרהֶ/חָצֵ֑רוְ/אֵ֨תכָּל־יִתְדֹ֧תהַ/מִּשְׁכָּ֛ןוְ/אֶת־כָּל־יִתְדֹ֥תהֶ/חָצֵ֖רסָבִֽיב׃'),
(1505821,52,2,39,1,'וּ/מִן־הַ/תְּכֵ֤לֶתוְ/הָֽ/אַרְגָּמָן֙וְ/תוֹלַ֣עַתהַ/שָּׁנִ֔יעָשׂ֥וּבִגְדֵי־שְׂרָ֖דלְ/שָׁרֵ֣תבַּ/קֹּ֑דֶשׁוַֽ/יַּעֲשׂ֞וּאֶת־בִּגְדֵ֤יהַ/קֹּ֙דֶשׁ֙אֲשֶׁ֣רלְ/אַהֲרֹ֔ןכַּ/אֲשֶׁ֛רצִוָּ֥היְהוָ֖האֶת־מֹשֶֽׁה׃'),
(1505822,52,2,39,2,'וַ/יַּ֖עַשׂאֶת־הָ/אֵפֹ֑דזָהָ֗בתְּכֵ֧לֶתוְ/אַרְגָּמָ֛ןוְ/תוֹלַ֥עַתשָׁנִ֖יוְ/שֵׁ֥שׁמָשְׁזָֽר׃'),
(1505823,52,2,39,3,'וַֽ/יְרַקְּע֞וּאֶת־פַּחֵ֣יהַ/זָּהָב֮וְ/קִצֵּ֣ץפְּתִילִם֒לַ/עֲשׂ֗וֹתבְּ/ת֤וֹךְהַ/תְּכֵ֙לֶת֙וּ/בְ/ת֣וֹךְהָֽ/אַרְגָּמָ֔ןוּ/בְ/ת֛וֹךְתּוֹלַ֥עַתהַ/שָּׁנִ֖יוּ/בְ/ת֣וֹךְהַ/שֵּׁ֑שׁמַעֲשֵׂ֖החֹשֵֽׁב׃'),
(1505824,52,2,39,4,'כְּתֵפֹ֥תעָֽשׂוּ־ל֖/וֹחֹבְרֹ֑תעַל־שְׁנֵ֥יחֻבָּֽר׃'),
(1505825,52,2,39,5,'וְ/חֵ֨שֶׁבאֲפֻדָּת֜/וֹאֲשֶׁ֣רעָלָ֗י/ומִמֶּ֣/נּוּהוּא֮כְּ/מַעֲשֵׂ/הוּ֒זָהָ֗בתְּכֵ֧לֶתוְ/אַרְגָּמָ֛ןוְ/תוֹלַ֥עַתשָׁנִ֖יוְ/שֵׁ֣שׁמָשְׁזָ֑רכַּ/אֲשֶׁ֛רצִוָּ֥היְהוָ֖האֶת־מֹשֶֽׁה׃'),
(1505826,52,2,39,6,'וַֽ/יַּעֲשׂוּ֙אֶת־אַבְנֵ֣יהַ/שֹּׁ֔הַםמֻֽסַבֹּ֖תמִשְׁבְּצֹ֣תזָהָ֑במְפֻתָּחֹת֙פִּתּוּחֵ֣יחוֹתָ֔םעַל־שְׁמ֖וֹתבְּנֵ֥ייִשְׂרָאֵֽל׃'),
(1505827,52,2,39,7,'וַ/יָּ֣שֶׂםאֹתָ֗/םעַ֚לכִּתְפֹ֣תהָ/אֵפֹ֔דאַבְנֵ֥יזִכָּר֖וֹןלִ/בְנֵ֣ייִשְׂרָאֵ֑לכַּ/אֲשֶׁ֛רצִוָּ֥היְהוָ֖האֶת־מֹשֶֽׁה׃'),
(1505828,52,2,39,8,'וַ/יַּ֧עַשׂאֶת־הַ/חֹ֛שֶׁןמַעֲשֵׂ֥החֹשֵׁ֖בכְּ/מַעֲשֵׂ֣האֵפֹ֑דזָהָ֗בתְּכֵ֧לֶתוְ/אַרְגָּמָ֛ןוְ/תוֹלַ֥עַתשָׁנִ֖יוְ/שֵׁ֥שׁמָשְׁזָֽר׃'),
(1505829,52,2,39,9,'רָב֧וּעַהָיָ֛הכָּפ֖וּלעָשׂ֣וּאֶת־הַ/חֹ֑שֶׁןזֶ֧רֶתאָרְכּ֛/וֹוְ/זֶ֥רֶתרָחְבּ֖/וֹכָּפֽוּל׃'),
(1505830,52,2,39,10,'וַ/יְמַלְאוּ־ב֔/וֹאַרְבָּעָ֖הט֣וּרֵיאָ֑בֶןט֗וּראֹ֤דֶםפִּטְדָה֙וּ/בָרֶ֔קֶתהַ/טּ֖וּרהָ/אֶחָֽד׃'),
(1505831,52,2,39,11,'וְ/הַ/טּ֖וּרהַ/שֵּׁנִ֑ינֹ֥פֶךְסַפִּ֖ירוְ/יָהֲלֹֽם׃'),
(1505832,52,2,39,12,'וְ/הַ/טּ֖וּרהַ/שְּׁלִישִׁ֑ילֶ֥שֶׁםשְׁב֖וֹוְ/אַחְלָֽמָה׃'),
(1505833,52,2,39,13,'וְ/הַ/טּוּר֙הָֽ/רְבִיעִ֔יתַּרְשִׁ֥ישׁשֹׁ֖הַםוְ/יָשְׁפֵ֑המֽוּסַבֹּ֛תמִשְׁבְּצ֥וֹתזָהָ֖בבְּ/מִלֻּאֹתָֽ/ם׃'),
(1505834,52,2,39,14,'וְ֠/הָ/אֲבָנִיםעַל־שְׁמֹ֨תבְּנֵי־יִשְׂרָאֵ֥להֵ֛נָּהשְׁתֵּ֥יםעֶשְׂרֵ֖העַל־שְׁמֹתָ֑/םפִּתּוּחֵ֤יחֹתָם֙אִ֣ישׁעַל־שְׁמ֔/וֹלִ/שְׁנֵ֥יםעָשָׂ֖רשָֽׁבֶט׃'),
(1505835,52,2,39,15,'וַ/יַּעֲשׂ֧וּעַל־הַ/חֹ֛שֶׁןשַׁרְשְׁרֹ֥תגַּבְלֻ֖תמַעֲשֵׂ֣העֲבֹ֑תזָהָ֖בטָהֽוֹר׃'),
(1505836,52,2,39,16,'וַֽ/יַּעֲשׂ֗וּשְׁתֵּי֙מִשְׁבְּצֹ֣תזָהָ֔בוּ/שְׁתֵּ֖יטַבְּעֹ֣תזָהָ֑בוַֽ/יִּתְּנ֗וּאֶת־שְׁתֵּי֙הַ/טַּבָּעֹ֔תעַל־שְׁנֵ֖יקְצ֥וֹתהַ/חֹֽשֶׁן׃'),
(1505837,52,2,39,17,'וַֽ/יִּתְּנ֗וּשְׁתֵּי֙הָ/עֲבֹתֹ֣תהַ/זָּהָ֔בעַל־שְׁתֵּ֖יהַ/טַּבָּעֹ֑תעַל־קְצ֖וֹתהַ/חֹֽשֶׁן׃'),
(1505838,52,2,39,18,'וְ/אֵ֨תשְׁתֵּ֤יקְצוֹת֙שְׁתֵּ֣יהָֽ/עֲבֹתֹ֔תנָתְנ֖וּעַל־שְׁתֵּ֣יהַֽ/מִּשְׁבְּצֹ֑תוַֽ/יִּתְּנֻ֛/םעַל־כִּתְפֹ֥תהָ/אֵפֹ֖דאֶל־מ֥וּלפָּנָֽי/ו׃'),
(1505839,52,2,39,19,'וַֽ/יַּעֲשׂ֗וּשְׁתֵּי֙טַבְּעֹ֣תזָהָ֔בוַ/יָּשִׂ֕ימוּעַל־שְׁנֵ֖יקְצ֣וֹתהַ/חֹ֑שֶׁןעַל־שְׂפָת֕/וֹאֲשֶׁ֛ראֶל־עֵ֥בֶרהָ/אֵפֹ֖דבָּֽיְתָ/ה׃'),
(1505840,52,2,39,20,'וַֽ/יַּעֲשׂוּ֮שְׁתֵּ֣יטַבְּעֹ֣תזָהָב֒וַֽ/יִּתְּנֻ֡/םעַל־שְׁתֵּי֩כִתְפֹ֨תהָ/אֵפֹ֤דמִ/לְ/מַ֙טָּה֙מִ/מּ֣וּלפָּנָ֔י/ולְ/עֻמַּ֖תמֶחְבַּרְתּ֑/וֹמִ/מַּ֕עַללְ/חֵ֖שֶׁבהָ/אֵפֹֽד׃'),
(1505841,52,2,39,21,'וַ/יִּרְכְּס֣וּאֶת־הַ/חֹ֡שֶׁןמִ/טַּבְּעֹתָי/ו֩אֶל־טַבְּעֹ֨תהָ/אֵפֹ֜דבִּ/פְתִ֣ילתְּכֵ֗לֶתלִֽ/הְיֹת֙עַל־חֵ֣שֶׁבהָ/אֵפֹ֔דוְ/לֹֽא־יִזַּ֣חהַ/חֹ֔שֶׁןמֵ/עַ֖להָ/אֵפֹ֑דכַּ/אֲשֶׁ֛רצִוָּ֥היְהוָ֖האֶת־מֹשֶֽׁה׃'),
(1505842,52,2,39,22,'וַ/יַּ֛עַשׂאֶת־מְעִ֥ילהָ/אֵפֹ֖דמַעֲשֵׂ֣האֹרֵ֑גכְּלִ֖ילתְּכֵֽלֶת׃'),
(1505843,52,2,39,23,'וּ/פִֽי־הַ/מְּעִ֥ילבְּ/תוֹכ֖/וֹכְּ/פִ֣יתַחְרָ֑אשָׂפָ֥הלְ/פִ֛י/וסָבִ֖יבלֹ֥איִקָּרֵֽעַ׃'),
(1505844,52,2,39,24,'וַֽ/יַּעֲשׂוּ֙עַל־שׁוּלֵ֣יהַ/מְּעִ֔ילרִמּוֹנֵ֕יתְּכֵ֥לֶתוְ/אַרְגָּמָ֖ןוְ/תוֹלַ֣עַתשָׁנִ֑ימָשְׁזָֽר׃'),
(1505845,52,2,39,25,'וַ/יַּעֲשׂ֥וּפַעֲמֹנֵ֖יזָהָ֣בטָה֑וֹרוַ/יִּתְּנ֨וּאֶת־הַ/פַּֽעֲמֹנִ֜יםבְּ/ת֣וֹךְהָ/רִמֹּנִ֗יםעַל־שׁוּלֵ֤יהַ/מְּעִיל֙סָבִ֔יבבְּ/ת֖וֹךְהָ/רִמֹּנִֽים׃'),
(1505846,52,2,39,26,'פַּעֲמֹ֤ןוְ/רִמֹּן֙פַּעֲמֹ֣ןוְ/רִמֹּ֔ןעַל־שׁוּלֵ֥יהַ/מְּעִ֖ילסָבִ֑יבלְ/שָׁרֵ֕תכַּ/אֲשֶׁ֛רצִוָּ֥היְהוָ֖האֶת־מֹשֶֽׁה׃');
